import asyncio

import asyncpg


class UserRepository:
    def __init__(self, pool: asyncpg.Pool) -> None:
        self.pool = pool

    async def get(self, user_id: int) -> asyncpg.Record | None:
        return await self.pool.fetchrow("SELECT * FROM users WHERE id = $1", user_id)

    async def get_many(self, user_ids: list[int]) -> list[asyncpg.Record | None]:
        return await asyncio.gather(*(self.get(uid) for uid in user_ids))

import asyncio


async def _normalize(record: dict) -> dict:
    return {k.strip().lower(): (v.strip() if isinstance(v, str) else v) for k, v in record.items()}


async def normalize_all(records: list[dict]) -> list[dict]:
    return await asyncio.gather(*[_normalize(r) for r in records])

from datetime import date
from decimal import Decimal

from pydantic import BaseModel, Field


class InvoiceLine(BaseModel):
    description: str
    quantity: int = Field(gt=0)
    unit_price: Decimal


class Invoice(BaseModel):
    number: str
    issued_on: date
    lines: list[InvoiceLine]

    @property
    def total(self) -> Decimal:
        return sum((line.quantity * line.unit_price for line in self.lines), Decimal("0"))

